#!/usr/bin/env bash
role_host(){ [[ $1 == iran ]]&&printf '%s' "$IRAN_IP"||printf '%s' "$FOREIGN_IP"; }; remote_exec(){ local role=$1;shift;local host;host=$(role_host "$role");local -a opts=(-p "$SSH_PORT" -o BatchMode=yes -o ConnectTimeout=10 -o StrictHostKeyChecking=accept-new);[[ -n ${SSH_KEY:-} ]]&&opts+=(-i "$SSH_KEY");ssh "${opts[@]}" "$SSH_USER@$host" "$@"; }; remote_sync_runtime(){ local role=$1 host;host=$(role_host "$role");local -a opts=(-p "$SSH_PORT" -o BatchMode=yes -o ConnectTimeout=10 -o StrictHostKeyChecking=accept-new);[[ -n ${SSH_KEY:-} ]]&&opts+=(-i "$SSH_KEY");tar -C "$TF_ETC" -czf - config.toml secrets/health.token|ssh "${opts[@]}" "$SSH_USER@$host" 'sudo mkdir -p /etc/tunnelforge/secrets && sudo tar -C /etc/tunnelforge -xzf - && sudo chmod 600 /etc/tunnelforge/config.toml /etc/tunnelforge/secrets/health.token'; }
